// Keyed archives of NSURLResponse, NSHTTPURLResponse and NSCachedURLResponse in the layout of macOS (see the comments
// at encodeResponseArchive in src/URL/NSURLResponse.m and at -[NSCachedURLResponse initWithCoder:] in
// src/URL/NSURLCache.m). The documentation gives no archive layout; the layout is what archives written by macOS
// 26.7.3 and 10.14.4 (x86_64 and i386) contain, read as property lists.
//
// - Archives written by those systems, embedded below as base 64 (fixtures), decode here to the values macOS decodes
//   them to, in a plain and a secure unarchiver.
// - Archives written here and embedded below the same way (source "darling": written by this implementation on x86_64
//   and i386) decode on macOS 26.7.3 and 10.14.4 to the same values; the file is built and run there as well.
// - What this implementation writes is checked against what macOS writes: the same objects are archived and both
//   archives are read back by classes that record the layout (the integers, the properties and their classes and
//   the user info property list), and the two records are compared.
// - QUIRK tests: test_quirk_secure_user_info_with_other_classes, test_quirk_nil_mime_type_is_octet_stream.
// Built without ARC. Run without arguments. "dump" prints how each fixture decodes (used to make the expected
// values from macOS 26.7.3), "write <dir>" writes the archives of this implementation to <dir>, "strict" also runs the
// checks of malformed archives (this implementation's validation; macOS is more permissive).
#import <Foundation/Foundation.h>
#include <stdio.h>
#include <string.h>
#include <float.h>

@interface NSKeyedUnarchiver (SecureCodingTestDeclaration)
- (void)setRequiresSecureCoding:(BOOL)flag;
@end

static int failures;
#define CHECK(cond) do { if (!(cond)) { printf("FAIL line %d: %s\n", __LINE__, #cond); failures++; } } while (0)
#define CHECK_EQ(actual, expected, what) do { NSString *a_ = (actual), *e_ = (expected); if (![a_ isEqualToString:e_]) { printf("FAIL line %d: %s\n  got:      %s\n  expected: %s\n", __LINE__, what, [a_ UTF8String], [e_ UTF8String]); failures++; } } while (0)

typedef struct { const char *name; const char *source; int secure; const char *base64; } Fixture;
typedef struct { const char *name; const char *expected; } Expected;

