// ---- describing decoded objects: the same text on every system for the same decoded values

static NSString *fmt(id o) {
    if (o == nil) return @"(nil)";
    if ([o isKindOfClass:[NSString class]]) return o;
    if ([o isKindOfClass:[NSNumber class]]) return [o description];
    if ([o isKindOfClass:[NSData class]]) {
        NSMutableString *s = [NSMutableString stringWithString:@"<"];
        const unsigned char *p = [o bytes];
        for (NSUInteger i = 0; i < [o length]; i++) [s appendFormat:@"%02x", p[i]];
        return [s stringByAppendingString:@">"];
    }
    if ([o isKindOfClass:[NSDate class]]) return [NSString stringWithFormat:@"date(%.0f)", [o timeIntervalSince1970]];
    if ([o isKindOfClass:[NSDictionary class]]) {
        NSMutableString *s = [NSMutableString stringWithString:@"{"];
        NSArray *keys = [[o allKeys] sortedArrayUsingComparator:^NSComparisonResult(id a, id b) { return [[a description] compare:[b description]]; }];
        for (id k in keys) [s appendFormat:@" %@=%@;", fmt(k), fmt([o objectForKey:k])];
        return [s stringByAppendingString:@" }"];
    }
    if ([o isKindOfClass:[NSArray class]]) {
        NSMutableArray *parts = [NSMutableArray array];
        for (id x in o) [parts addObject:fmt(x)];
        return [NSString stringWithFormat:@"(%@)", [parts componentsJoinedByString:@","]];
    }
    return [NSString stringWithFormat:@"<%@>", NSStringFromClass([o class])];
}

static NSString *describeResponse(NSURLResponse *r) {
    if (!r) return @"response=(nil)";
    NSMutableString *s = [NSMutableString stringWithFormat:@"%@ url=%@ base=%@ mime=%@ len=%lld enc=%@", NSStringFromClass([r class]),
        [[r URL] absoluteString] ?: @"(nil)", [[[r URL] baseURL] absoluteString] ?: @"(nil)", [r MIMEType] ?: @"(nil)", [r expectedContentLength], [r textEncodingName] ?: @"(nil)"];
    if ([r isKindOfClass:[NSHTTPURLResponse class]])
        [s appendFormat:@" status=%ld headers=%@", (long)[(NSHTTPURLResponse *)r statusCode], fmt([(NSHTTPURLResponse *)r allHeaderFields])];
    return s;
}

// withPolicy is NO where the storage policy of the decoded object is not defined (see the QUIRK test).
static NSString *describe(id o, BOOL withPolicy) {
    if ([o isKindOfClass:[NSCachedURLResponse class]]) {
        NSCachedURLResponse *c = o;
        NSString *policy = withPolicy ? [NSString stringWithFormat:@"%ld", (long)[c storagePolicy]] : @"*";
        return [NSString stringWithFormat:@"cached policy=%@ data=%@ info=%@ | %@", policy, fmt([c data]), fmt([c userInfo]), describeResponse([c response])];
    }
    if ([o isKindOfClass:[NSURLResponse class]]) return describeResponse(o);
    return o ? @"(other object)" : @"nil";
}

static BOOL isCached(const char *name) { return name[0] == 'c'; }
// A secure decode of a cached response whose archived user info holds an array, a date, null or a URL gives an object
// without data and user info (see the QUIRK test); the same archive decodes normally without secure coding.
static BOOL isRefusedUserInfo(const char *name, int secure) {
    return secure && isCached(name) && (strstr(name, "cu-array") == name || strstr(name, "cu-date") == name || strstr(name, "cu-null") == name || strstr(name, "cu-url") == name);
}

static id decodeArchive(NSData *data, const char *name, BOOL secure) {
    NSKeyedUnarchiver *u = [[[NSKeyedUnarchiver alloc] initForReadingFromData:data error:NULL] autorelease];
    [u setRequiresSecureCoding:secure];
    id r = nil;
    @try {
        r = [u decodeObjectOfClass:isCached(name) ? [NSCachedURLResponse class] : [NSURLResponse class] forKey:NSKeyedArchiveRootObjectKey];
    } @catch (NSException *exception) {
        r = nil;
    }
    [u finishDecoding];
    return r;
}

static NSData *archiveObject(id obj, BOOL secure) {
    NSKeyedArchiver *a = [[[NSKeyedArchiver alloc] initRequiringSecureCoding:secure] autorelease];
    [a encodeObject:obj forKey:NSKeyedArchiveRootObjectKey];
    [a finishEncoding];
    return [a encodedData];
}

static const char *expectedFor(const char *name, int secure) {
    char key[128];
    snprintf(key, sizeof key, "%s.%s", name, secure ? "secure" : "plain");
    for (size_t i = 0; i < sizeof expectations / sizeof expectations[0]; i++)
        if (!strcmp(expectations[i].name, key)) return expectations[i].expected;
    for (size_t i = 0; i < sizeof expectations / sizeof expectations[0]; i++)
        if (!strcmp(expectations[i].name, name)) return expectations[i].expected;
    return NULL;
}

// ---- the objects whose archives are compared

static NSURL *baseURL(void) { return [NSURL URLWithString:@"http://example.test/page.html"]; }
static NSData *bodyData(void) { return [@"<html>cached body</html>" dataUsingEncoding:NSUTF8StringEncoding]; }

static id makeCase(const char *name) {
    NSURL *u = baseURL();
    NSData *body = bodyData();
    NSString *n = [NSString stringWithUTF8String:name];
    NSMutableDictionary *resp = [NSMutableDictionary dictionary];
    resp[@"rp1"] = [[[NSURLResponse alloc] initWithURL:u MIMEType:@"text/plain" expectedContentLength:24 textEncodingName:nil] autorelease];
    resp[@"rp2"] = [[[NSURLResponse alloc] initWithURL:u MIMEType:@"text/html" expectedContentLength:-1 textEncodingName:@"utf-8"] autorelease];
    resp[@"rp3"] = [[[NSURLResponse alloc] initWithURL:nil MIMEType:nil expectedContentLength:0 textEncodingName:nil] autorelease];
    resp[@"rp5"] = [[[NSURLResponse alloc] initWithURL:[NSURL URLWithString:@"page.html" relativeToURL:[NSURL URLWithString:@"http://example.test/dir/"]] MIMEType:@"text/plain" expectedContentLength:3 textEncodingName:nil] autorelease];
    resp[@"h1"] = [[[NSHTTPURLResponse alloc] initWithURL:u statusCode:200 HTTPVersion:@"HTTP/1.1" headerFields:@{@"Content-Type": @"text/html; charset=utf-8", @"X-Probe": @"1"}] autorelease];
    resp[@"h2"] = [[[NSHTTPURLResponse alloc] initWithURL:u statusCode:404 HTTPVersion:@"HTTP/1.0" headerFields:nil] autorelease];
    resp[@"h6"] = [[[NSHTTPURLResponse alloc] initWithURL:u statusCode:200 HTTPVersion:@"HTTP/1.1" headerFields:@{@"Content-Type": @"text/plain; charset=iso-8859-1", @"Content-Encoding": @"gzip", @"Content-Length": @"24"}] autorelease];
    if ([n hasPrefix:@"resp-"]) return resp[[n substringFromIndex:5]];
    if ([n hasPrefix:@"c-"]) return [[[NSCachedURLResponse alloc] initWithResponse:resp[[n substringFromIndex:2]] data:body userInfo:nil storagePolicy:NSURLCacheStorageAllowed] autorelease];
    NSURLResponse *h1 = resp[@"h1"];
    if ([n hasPrefix:@"cp-policy"]) {
        NSURLCacheStoragePolicy pol[] = {NSURLCacheStorageAllowed, NSURLCacheStorageAllowedInMemoryOnly, NSURLCacheStorageNotAllowed};
        return [[[NSCachedURLResponse alloc] initWithResponse:h1 data:body userInfo:nil storagePolicy:pol[[[n substringFromIndex:9] intValue]]] autorelease];
    }
    if ([n isEqualToString:@"cp-data-empty"])
        return [[[NSCachedURLResponse alloc] initWithResponse:h1 data:[NSData data] userInfo:nil storagePolicy:NSURLCacheStorageAllowed] autorelease];
    NSMutableDictionary *infos = [NSMutableDictionary dictionary];
    infos[@"empty"] = @{};
    infos[@"three"] = @{@"name": @"value", @"count": @3, @"z": @"last"};
    infos[@"data"] = @{@"k": [NSData dataWithBytes:"\1\2" length:2]};
    infos[@"nested"] = @{@"k": @{@"a": @1}};
    infos[@"array"] = @{@"k": @[@"a", @2]};
    infos[@"date"] = @{@"k": [NSDate dateWithTimeIntervalSince1970:1000]};
    infos[@"url"] = @{@"k": [NSURL URLWithString:@"http://x/"]};
    infos[@"null"] = @{@"k": [NSNull null]};
    infos[@"numkey"] = @{@1: @2};
    if ([n hasPrefix:@"cu-"])
        return [[[NSCachedURLResponse alloc] initWithResponse:h1 data:body userInfo:infos[[n substringFromIndex:3]] storagePolicy:NSURLCacheStorageAllowed] autorelease];
    return nil;
}

static const char *caseNames[] = {
    "resp-rp1", "resp-rp2", "resp-rp3", "resp-rp5", "resp-h1", "resp-h2", "resp-h6",
    "c-rp1", "c-h1", "c-h6", "cp-policy2", "cp-data-empty",
    "cu-three", "cu-data", "cu-nested", "cu-array", "cu-date", "cu-url", "cu-null", "cu-numkey",
};

// ---- recording the layout: classes that stand in for the archived ones and describe what they read

static NSString *lastResponseSignature;

static NSString *signatureOf(id p) {
    if (p == nil) return @"null";
    if ([p isKindOfClass:[NSURL class]]) return @"URL";
    if ([p isKindOfClass:[NSNumber class]]) {
        double d = [p doubleValue];
        if (CFNumberIsFloatType((CFNumberRef)p)) return d == DBL_MAX ? @"double(max)" : @"double";
        return [NSString stringWithFormat:@"int(%lld)", [p longLongValue]];
    }
    if ([p isKindOfClass:[NSString class]]) return [NSString stringWithFormat:@"string(%@)", [p hasPrefix:@"\r\n\r\n"] ? @"order" : p];
    if ([p isKindOfClass:[NSDictionary class]]) {
        NSMutableArray *keys = [NSMutableArray array];
        for (id k in p) [keys addObject:k];
        return [NSString stringWithFormat:@"dictionary(%@)", [[keys sortedArrayUsingSelector:@selector(compare:)] componentsJoinedByString:@","]];
    }
    return [NSString stringWithFormat:@"other(%@)", NSStringFromClass([p class])];
}

static NSSet *wideClasses(void) {
    return [NSSet setWithObjects:[NSURL class], [NSNumber class], [NSString class], [NSDictionary class], [NSData class], [NSArray class], [NSDate class], [NSNull class], nil];
}

@interface SpyResponse : NSObject <NSSecureCoding> @end
@implementation SpyResponse
+ (BOOL)supportsSecureCoding { return YES; }
- (id)initWithCoder:(NSCoder *)c {
    int format = -1, http = -1, count = -1;
    [c decodeValueOfObjCType:@encode(int) at:&format size:sizeof format];
    [c decodeValueOfObjCType:@encode(int) at:&http size:sizeof http];
    [c decodeValueOfObjCType:@encode(int) at:&count size:sizeof count];
    NSMutableString *sig = [NSMutableString stringWithFormat:@"%d,%d,%d", format, http, count];
    BOOL keyed = [c containsValueForKey:@"__nsurlrequest_proto_prop_obj_0"];
    [sig appendString:keyed ? @" keyed:" : @" unkeyed:"];
    for (int i = 0; i < count; i++) {
        id p = keyed ? [c decodeObjectOfClasses:wideClasses() forKey:[NSString stringWithFormat:@"__nsurlrequest_proto_prop_obj_%d", i]] : [c decodeObject];
        [sig appendFormat:@" %@", signatureOf(p)];
    }
    if (http == 1) {
        // The last value is a boolean (NO) on macOS and an integer here; Darling's unarchiver does not read the one as
        // the other, and the implementation under test does not need it, so only the number before it is recorded.
        int nine = -1;
        [c decodeValueOfObjCType:@encode(int) at:&nine size:sizeof nine];
        [sig appendFormat:@" tail(%d)", nine];
    }
    [lastResponseSignature release];
    lastResponseSignature = [sig retain];
    return [super init];
}
@end

static NSString *cachedSignature;

@interface SpyCached : NSObject <NSSecureCoding> @end
@implementation SpyCached
+ (BOOL)supportsSecureCoding { return YES; }
- (id)initWithCoder:(NSCoder *)c {
    int format = -1, policy = -1;
    [c decodeValueOfObjCType:@encode(int) at:&format size:sizeof format];
    [c decodeValueOfObjCType:@encode(int) at:&policy size:sizeof policy];
    NSMutableString *sig = [NSMutableString stringWithFormat:@"%d,%d", format, policy];
    [c decodeObjectOfClass:[SpyResponse class] forKey:@"_NSURLResponseType"];
    [sig appendFormat:@" response[%@]", lastResponseSignature];
    NSArray *keys = @[@"_CFCachedURLResponseReceiverDataArray", @"_NSDataType", @"_NSDictionaryType", @"_CFCachedURLResponseUserInfo"];
    for (NSString *key in keys) {
        id v = [c containsValueForKey:key] ? [c decodeObjectOfClasses:wideClasses() forKey:key] : nil;
        NSString *text;
        if ([key isEqualToString:@"_CFCachedURLResponseUserInfo"] && v) {
            id list = [NSPropertyListSerialization propertyListWithData:v options:NSPropertyListImmutable format:NULL error:NULL];
            text = [NSString stringWithFormat:@"propertylist(%@)", fmt(list)];
        } else if ([v isKindOfClass:[NSArray class]]) {
            text = [NSString stringWithFormat:@"array(%@)", fmt(v)];
        } else if ([v isKindOfClass:[NSData class]]) {
            text = [NSString stringWithFormat:@"data(%lu)", (unsigned long)[v length]];
        } else if ([v isKindOfClass:[NSDictionary class]]) {
            text = [NSString stringWithFormat:@"dictionary%@", fmt(v)];
        } else text = v ? signatureOf(v) : @"absent-or-null";
        [sig appendFormat:@" %@=%@", key, text];
    }
    [cachedSignature release];
    cachedSignature = [sig retain];
    return [super init];
}
@end

static NSString *layoutOf(NSData *data, const char *name, BOOL secure) {
    NSKeyedUnarchiver *u = [[[NSKeyedUnarchiver alloc] initForReadingFromData:data error:NULL] autorelease];
    [u setRequiresSecureCoding:secure];
    [u setClass:[SpyResponse class] forClassName:@"NSURLResponse"];
    [u setClass:[SpyResponse class] forClassName:@"NSHTTPURLResponse"];
    [u setClass:[SpyCached class] forClassName:@"NSCachedURLResponse"];
    id r = nil;
    @try {
        r = [u decodeObjectOfClass:isCached(name) ? [SpyCached class] : [SpyResponse class] forKey:NSKeyedArchiveRootObjectKey];
    } @catch (NSException *exception) {
        return [NSString stringWithFormat:@"exception %@", [exception name]];
    }
    [u finishDecoding];
    return r ? [[(isCached(name) ? cachedSignature : lastResponseSignature) copy] autorelease] : @"nil";
}

// ---- the tests

static const char *sourceNames[] = {"macos26", "mojave64", "mojave32", "darling"};

static void test_fixtures_decode_as_on_macos(void) {
    int decoded = 0;
    for (size_t i = 0; i < sizeof fixtures / sizeof fixtures[0]; i++) {
        const Fixture *f = &fixtures[i];
        NSData *d = [[[NSData alloc] initWithBase64EncodedString:[NSString stringWithUTF8String:f->base64] options:0] autorelease];
        CHECK(d != nil);
        const char *want = expectedFor(f->name, f->secure);
        if (!want) { printf("FAIL: no expected value for %s\n", f->name); failures++; continue; }
        id r = decodeArchive(d, f->name, f->secure);
        BOOL refused = isRefusedUserInfo(f->name, f->secure);
        NSString *got = describe(r, !refused);
        if (![got isEqualToString:[NSString stringWithUTF8String:want]]) {
            printf("FAIL: %s (%s, %s)\n  got:      %s\n  expected: %s\n", f->name, f->source, f->secure ? "secure" : "plain", [got UTF8String], want);
            failures++;
        }
        decoded++;
    }
    CHECK(decoded > 40);
}

// What this implementation writes decodes to what macOS decodes the same objects to, and has the layout of macOS.
static void test_own_archives_have_the_layout_of_macos(void) {
    for (size_t i = 0; i < sizeof caseNames / sizeof caseNames[0]; i++) {
        const char *name = caseNames[i];
        for (int secure = 0; secure < 2; secure++) {
            id obj = makeCase(name);
            NSData *mine = archiveObject(obj, secure);
            // Reading back: the same values as macOS reads from its own archive of the object.
            const char *want = expectedFor(name, secure);
            id back = decodeArchive(mine, name, secure);
            if (want) CHECK_EQ(describe(back, !isRefusedUserInfo(name, secure)), [NSString stringWithUTF8String:want], name);
            // The layout: the record made from a macOS fixture of the same case equals the record made from the archive here.
            for (size_t j = 0; j < sizeof fixtures / sizeof fixtures[0]; j++) {
                const Fixture *f = &fixtures[j];
                if (strcmp(f->name, name) || f->secure != secure || strcmp(f->source, "macos26")) continue;
                NSData *theirs = [[[NSData alloc] initWithBase64EncodedString:[NSString stringWithUTF8String:f->base64] options:0] autorelease];
                NSString *a = layoutOf(theirs, name, secure), *b = layoutOf(mine, name, secure);
                CHECK_EQ(b, a, name);
            }
        }
    }
}

// An archived cached response has data and user info that can be read again, also through a second round trip.
static void test_round_trip_of_decoded_objects(void) {
    for (int secure = 0; secure < 2; secure++) {
        NSCachedURLResponse *c = makeCase("cu-three");
        NSCachedURLResponse *back = decodeArchive(archiveObject(c, secure), "cu-three", secure);
        NSCachedURLResponse *again = decodeArchive(archiveObject(back, secure), "cu-three", secure);
        CHECK([again.data isEqualToData:bodyData()]);
        CHECK([again.userInfo isEqualToDictionary:[c userInfo]]);
        CHECK(again.storagePolicy == NSURLCacheStorageAllowed);
        CHECK([again.response isKindOfClass:[NSHTTPURLResponse class]] && [(NSHTTPURLResponse *)again.response statusCode] == 200);
        NSCachedURLResponse *empty = decodeArchive(archiveObject(makeCase("cp-data-empty"), secure), "cp-data-empty", secure);
        CHECK(empty != nil && [empty.data length] == 0);
    }
}

// QUIRK: a secure unarchiver does not refuse a cached response whose archived user info holds an array, a date, null or
// a URL; it returns an object with the response, no data and no user info (macOS 26.7.3 and 10.14.4, black-box
// observation, tier 2). Without secure coding the same archives decode with their user info (array and date) or without
// it (null and URL, which are not property list values).
static void test_quirk_secure_user_info_with_other_classes(void) {
    const char *names[] = {"cu-array", "cu-date", "cu-null", "cu-url"};
    for (int i = 0; i < 4; i++) {
        NSCachedURLResponse *secure = decodeArchive(archiveObject(makeCase(names[i]), YES), names[i], YES);
        CHECK(secure != nil);
        CHECK([secure.data length] == 0 && secure.userInfo == nil);
        CHECK([secure.response isKindOfClass:[NSHTTPURLResponse class]] && [(NSHTTPURLResponse *)secure.response statusCode] == 200);
        NSCachedURLResponse *plain = decodeArchive(archiveObject(makeCase(names[i]), NO), names[i], NO);
        CHECK(plain != nil && [plain.data isEqualToData:bodyData()]);
        BOOL propertyList = i < 2;
        CHECK(propertyList ? plain.userInfo != nil : plain.userInfo == nil);
    }
    // A user info of strings, numbers, data and dictionaries is accepted by a secure unarchiver, with a non-string key too.
    NSCachedURLResponse *ok = decodeArchive(archiveObject(makeCase("cu-nested"), YES), "cu-nested", YES);
    CHECK(ok != nil && [ok.userInfo isEqualToDictionary:@{@"k": @{@"a": @1}}]);
    NSCachedURLResponse *numkey = decodeArchive(archiveObject(makeCase("cu-numkey"), YES), "cu-numkey", YES);
    CHECK(numkey != nil && numkey.userInfo == nil && [numkey.data isEqualToData:bodyData()]);
}

// QUIRK: an NSURLResponse made without a MIME type has application/octet-stream as its MIME type, whether or not it has
// a URL and a text encoding name (macOS 26.7.3 and 10.14.4, x86_64 and i386, black-box observation, tier 2).
static void test_quirk_nil_mime_type_is_octet_stream(void) {
    NSURL *u = baseURL();
    CHECK([[[[NSURLResponse alloc] initWithURL:u MIMEType:nil expectedContentLength:0 textEncodingName:nil] autorelease].MIMEType isEqualToString:@"application/octet-stream"]);
    CHECK([[[[NSURLResponse alloc] initWithURL:nil MIMEType:nil expectedContentLength:0 textEncodingName:nil] autorelease].MIMEType isEqualToString:@"application/octet-stream"]);
    CHECK([[[[NSURLResponse alloc] initWithURL:u MIMEType:nil expectedContentLength:-1 textEncodingName:@"utf-8"] autorelease].MIMEType isEqualToString:@"application/octet-stream"]);
    CHECK([[[[NSURLResponse alloc] initWithURL:nil MIMEType:@"text/plain" expectedContentLength:0 textEncodingName:nil] autorelease].MIMEType isEqualToString:@"text/plain"]);
}

// A nil HTTP version is HTTP/1.1 (macOS 26.7.3 and 10.14.4); it used to crash here.
static void test_nil_http_version(void) {
    NSHTTPURLResponse *r = [[[NSHTTPURLResponse alloc] initWithURL:baseURL() statusCode:200 HTTPVersion:nil headerFields:@{@"Content-Length": @"5"}] autorelease];
    CHECK(r != nil && r.statusCode == 200 && r.expectedContentLength == 5);
}

// Malformed archives: a wrong format number, a property count that does not fit, a property of the wrong class, a
// storage policy outside the three. macOS 26.7.3 accepts several of these (and traps on an archive without a response),
// so the checks run only with the argument "strict" (on Darling), where they pin this implementation's validation.
@interface Spoof : NSObject <NSSecureCoding> { @public NSArray *ints; NSDictionary *objects; }
@end
@implementation Spoof
+ (BOOL)supportsSecureCoding { return YES; }
- (void)encodeWithCoder:(NSCoder *)coder {
    for (NSNumber *n in ints) { int v = [n intValue]; [coder encodeValueOfObjCType:@encode(int) at:&v]; }
    for (NSString *key in objects) [coder encodeObject:objects[key] forKey:key];
}
- (id)initWithCoder:(NSCoder *)coder { return nil; }
@end

static id decodeSpoof(NSString *className, NSArray *ints, NSDictionary *objects, Class expected, BOOL secure) {
    Spoof *s = [[[Spoof alloc] init] autorelease];
    s->ints = ints; s->objects = objects;
    NSKeyedArchiver *a = [[[NSKeyedArchiver alloc] initRequiringSecureCoding:YES] autorelease];
    [a setClassName:className forClass:[Spoof class]];
    [a encodeObject:s forKey:NSKeyedArchiveRootObjectKey];
    [a finishEncoding];
    NSKeyedUnarchiver *u = [[[NSKeyedUnarchiver alloc] initForReadingFromData:[a encodedData] error:NULL] autorelease];
    [u setRequiresSecureCoding:secure];
    if ([u respondsToSelector:@selector(setDecodingFailurePolicy:)]) [(id)u setDecodingFailurePolicy:(NSInteger)1];
    id r = nil;
    @try { r = [u decodeObjectOfClass:expected forKey:NSKeyedArchiveRootObjectKey]; } @catch (NSException *exception) { r = nil; }
    [u finishDecoding];
    return r;
}

static NSString *propKey(int i) { return [NSString stringWithFormat:@"__nsurlrequest_proto_prop_obj_%d", i]; }

static void test_malformed_archives(void) {
    NSURL *u = baseURL();
    NSNumber *zero = @0;
    NSDictionary *plainProps = @{propKey(0): u, propKey(1): @1.5, propKey(2): zero, propKey(3): @"text/plain", propKey(4): @"utf-8", propKey(5): @24, propKey(6): @(DBL_MAX)};
    NSArray *good = @[@8, @0, @7];
    CHECK(decodeSpoof(@"NSURLResponse", good, plainProps, [NSURLResponse class], YES) != nil);
    CHECK(decodeSpoof(@"NSURLResponse", @[@9, @0, @7], plainProps, [NSURLResponse class], YES) == nil);   // format
    CHECK(decodeSpoof(@"NSURLResponse", @[@8, @1, @7], plainProps, [NSURLResponse class], YES) == nil);   // not a plain response
    CHECK(decodeSpoof(@"NSURLResponse", @[@8, @0, @500], plainProps, [NSURLResponse class], YES) == nil); // count
    CHECK(decodeSpoof(@"NSURLResponse", @[@8, @0, @-1], plainProps, [NSURLResponse class], YES) == nil);
    NSMutableDictionary *p = [[plainProps mutableCopy] autorelease];
    p[propKey(0)] = @"http://example.test/";                                                               // URL as a string
    CHECK(decodeSpoof(@"NSURLResponse", good, p, [NSURLResponse class], YES) == nil);
    p = [[plainProps mutableCopy] autorelease]; p[propKey(3)] = @5;                                         // MIME type as a number
    CHECK(decodeSpoof(@"NSURLResponse", good, p, [NSURLResponse class], YES) == nil);
    p = [[plainProps mutableCopy] autorelease]; p[propKey(4)] = [NSURL URLWithString:@"http://other.example.test/"]; // encoding as a URL
    CHECK(decodeSpoof(@"NSURLResponse", good, p, [NSURLResponse class], YES) == nil);
    // HTTP: a status code and header fields of the right classes.
    NSDictionary *httpProps = @{propKey(0): u, propKey(1): @1.5, propKey(2): zero, propKey(3): @204, propKey(4): @{@"X-A": @"1"}};
    NSArray *httpGood = @[@8, @1, @5];
    NSHTTPURLResponse *ok = decodeSpoof(@"NSHTTPURLResponse", httpGood, httpProps, [NSHTTPURLResponse class], YES);
    CHECK([ok isKindOfClass:[NSHTTPURLResponse class]] && ok.statusCode == 204 && [[ok.allHeaderFields objectForKey:@"X-A"] isEqualToString:@"1"]);
    p = [[httpProps mutableCopy] autorelease]; p[propKey(3)] = @"200";                                      // status as a string
    CHECK(decodeSpoof(@"NSHTTPURLResponse", httpGood, p, [NSHTTPURLResponse class], YES) == nil);
    p = [[httpProps mutableCopy] autorelease]; p[propKey(4)] = @"x";                                        // headers as a string
    CHECK(decodeSpoof(@"NSHTTPURLResponse", httpGood, p, [NSHTTPURLResponse class], YES) == nil);
    p = [[httpProps mutableCopy] autorelease]; p[propKey(4)] = @{@"a": @1};                                 // header value as a number
    CHECK(decodeSpoof(@"NSHTTPURLResponse", httpGood, p, [NSHTTPURLResponse class], YES) == nil);
    CHECK(decodeSpoof(@"NSHTTPURLResponse", @[@8, @0, @5], httpProps, [NSHTTPURLResponse class], YES) == nil); // flag of a plain response
    // Cached: the response, the data, the policy and the format number.
    NSURLResponse *resp = [[[NSURLResponse alloc] initWithURL:u MIMEType:@"text/plain" expectedContentLength:3 textEncodingName:nil] autorelease];
    NSDictionary *cachedGood = @{@"_NSURLResponseType": resp, @"_NSDataType": bodyData()};
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@12, @0], cachedGood, [NSCachedURLResponse class], YES) != nil);
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@13, @0], cachedGood, [NSCachedURLResponse class], YES) == nil);
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@12, @3], cachedGood, [NSCachedURLResponse class], YES) == nil);
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@12, @-1], cachedGood, [NSCachedURLResponse class], YES) == nil);
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@12, @0], @{@"_NSURLResponseType": resp}, [NSCachedURLResponse class], YES) == nil);
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@12, @0], @{@"_NSURLResponseType": @"http://example.test/", @"_NSDataType": bodyData()}, [NSCachedURLResponse class], YES) == nil);
    CHECK(decodeSpoof(@"NSCachedURLResponse", @[@12, @0], @{@"_NSURLResponseType": resp, @"_NSDataType": @"text"}, [NSCachedURLResponse class], YES) == nil);
    // The data may come from the array of data when the plain data entry is missing.
    NSCachedURLResponse *fromArray = decodeSpoof(@"NSCachedURLResponse", @[@12, @1], @{@"_NSURLResponseType": resp, @"_CFCachedURLResponseReceiverDataArray": @[bodyData()]}, [NSCachedURLResponse class], YES);
    CHECK([fromArray.data isEqualToData:bodyData()] && fromArray.storagePolicy == NSURLCacheStorageAllowedInMemoryOnly);
}

int main(int argc, char **argv) {
    @autoreleasepool {
        if (argc > 1 && !strcmp(argv[1], "dump")) {
            for (size_t i = 0; i < sizeof fixtures / sizeof fixtures[0]; i++) {
                const Fixture *f = &fixtures[i];
                NSData *d = [[[NSData alloc] initWithBase64EncodedString:[NSString stringWithUTF8String:f->base64] options:0] autorelease];
                printf("%s.%s|%s|%s\n", f->name, f->secure ? "secure" : "plain", f->source, [describe(decodeArchive(d, f->name, f->secure), !isRefusedUserInfo(f->name, f->secure)) UTF8String]);
            }
            return 0;
        }
        if (argc > 2 && !strcmp(argv[1], "write")) {
            for (size_t i = 0; i < sizeof caseNames / sizeof caseNames[0]; i++)
                for (int secure = 0; secure < 2; secure++)
                    [archiveObject(makeCase(caseNames[i]), secure) writeToFile:[NSString stringWithFormat:@"%s/%s.%s.archive", argv[2], caseNames[i], secure ? "secure" : "plain"] atomically:YES];
            return 0;
        }
        (void)sourceNames;
        test_fixtures_decode_as_on_macos();
        test_own_archives_have_the_layout_of_macos();
        test_round_trip_of_decoded_objects();
        test_quirk_secure_user_info_with_other_classes();
        test_quirk_nil_mime_type_is_octet_stream();
        test_nil_http_version();
        if (argc > 1 && !strcmp(argv[1], "strict")) test_malformed_archives();
        if (failures) { printf("%d failure(s)\n", failures); return 1; }
        printf("PASS: NSCachedURLResponse and NSURLResponse archives in the macOS layout\n");
    }
    return 0;
}
